"""Validation service for DQR3HL (DQRP4), generated by the DQVP pipeline.

In the BiodiversityObservation entity, when the detectionStatus attribute has the values {notDetected}, the breedingEvidence attribute of BiodiversityObservation entity must not contain values from the set {courtship, nesting, chicks}.

The check is the DQVP constraint c-dqr3hl. It reads the data in place with DuckDB
and returns the measured value and whether DQR3HL is satisfied. service.json records
where it comes from.

Run:  python validation_job.py [data folder]
"""
import operator
import sys
from pathlib import Path

import duckdb

DATA = Path(__file__).resolve().parent / '../../../tools/dqvp/data/heleade'
LOADS = {'observation': "read_csv_auto('{data}/observation.csv', types={ 'observedAt': 'VARCHAR' })"}          # table -> load expression; {data} is the data folder
MEASURE = 'select 100.0*count(*) filter (where ("breedingEvidence" IS NULL OR NOT ("breedingEvidence" IN (\'courtship\', \'nesting\', \'chicks\'))))/nullif(count(*),0) from "observation" where "detectionStatus" in (\'notDetected\')'
COMPARE, THRESHOLD = '>=', 100.0
OPS = {">=": operator.ge, "<=": operator.le, "==": operator.eq,
       ">": operator.gt, "<": operator.lt, "!=": operator.ne}


def run_validation(data_dir=DATA):
    """(measured value, satisfied); (None, None) when nothing can be measured."""
    con = duckdb.connect()
    for table, load in LOADS.items():
        con.execute(f'CREATE TABLE "{table}" AS SELECT * FROM '
                    + load.replace("{data}", Path(data_dir).as_posix()))
    value = con.execute(MEASURE).fetchone()[0]
    if value is None:
        return None, None
    value = round(float(value), 4)
    return value, OPS[COMPARE](value, THRESHOLD)


if __name__ == "__main__":
    value, ok = run_validation(sys.argv[1] if len(sys.argv) > 1 else DATA)
    print(f"DQR3HL  {value}  {'SATISFIED' if ok else 'VIOLATED'}")
